-- PE10_C3 EKB: root-cause register after full captured campaign, no duplicate engines.
-- DML only; LF Router ACT-0001 -> ACTUALIZACION_DB_LF -> Merge Train.
BEGIN;
DO $pe10_ekb$
DECLARE v_count int;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-PE10-C3-OUTPUT-SCHEMA-DRIFT-20261015-001') THEN
 INSERT INTO public.lf_error_knowledge(id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,lote_origen,pr,estado,evidencia,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref,created_at,updated_at,primera_vez,ultima_vez)
 VALUES(gen_random_uuid(),'LF-PE10-C3-OUTPUT-SCHEMA-DRIFT-20261015-001','PROFILE_EVOLUTION','Outputs de perfil con decisiones correctas pero contrato estructural incompleto','Campaña PE10_C3 V2: UI evolucionado R1 generó 20 errores de contrato; R2 reparó a cero. Product Director original T3 declaró PASS sin deliverable_created.authority_status y falló con FIELD_MISSING y AUTHORITY_STATUS. Las respuestas históricas se conservan, sin corregir RAW retrospectivamente.','La generación del modelo no aplicó de manera consistente el control final de serialización del contrato existente. Una decisión de negocio semánticamente acotada puede emitir PASS sin un campo contractual obligatorio, o valores de enums fuera del validador.','Output del perfil reporta PASS o NEEDS_ADJUSTMENT y apariencia material completa, pero validator existente detecta ausencia/enums/target/score; otras etapas del mismo perfil pueden pasar.','Mantener un único validador canónico por perfil; autocorrección estructural acotada una vez antes de output, sin inventar autoridad ni modificar RAW histórico. No duplicar esquemas o volver a correr la campaña por diferencias de formato.','RAW eventos Supabase 21041-21047; producto A T3 (21044) -> 2 errores; producto B T1/T2/T3 (21045-21047) -> 0 errores; UI B R2 (21041) -> 0 errores. Evidencia original R1 en 21028 -> 20 errores del validador.','HIGH',2,'PROFILE_UPDATER_EVOLUTION_IMPLEMENTATION_V1/PE10_C3','#2706;#2707','ACTIVO','supabase://public.lf_eventos/21028;supabase://public.lf_eventos/21041;supabase://public.lf_eventos/21044;supabase://public.lf_eventos/21047','construction',ARRAY['Architect']::text[],'UNCLASSIFIED_WITH_REASON','DETERMINISTIC_VALIDATOR','PROFILE_EVOLUTION_GPT_NATIVE_PAIRED_RAW','https://github.com/cristhianlujan/claude-persona-lf-patch/pull/2706',clock_timestamp(),clock_timestamp(),clock_timestamp(),clock_timestamp());
 END IF;
 SELECT count(*) INTO v_count FROM public.lf_error_knowledge WHERE codigo='LF-PE10-C3-OUTPUT-SCHEMA-DRIFT-20261015-001' AND titulo='Outputs de perfil con decisiones correctas pero contrato estructural incompleto' AND causa_raiz='La generación del modelo no aplicó de manera consistente el control final de serialización del contrato existente. Una decisión de negocio semánticamente acotada puede emitir PASS sin un campo contractual obligatorio, o valores de enums fuera del validador.' AND prevencion='Mantener un único validador canónico por perfil; autocorrección estructural acotada una vez antes de output, sin inventar autoridad ni modificar RAW histórico. No duplicar esquemas o volver a correr la campaña por diferencias de formato.';
 IF v_count<>1 THEN RAISE EXCEPTION 'PE10_EKB_READBACK_MISMATCH_1'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-PE10-C3-BROWSER-RAW-DURABILITY-20261015-001') THEN
 INSERT INTO public.lf_error_knowledge(id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,lote_origen,pr,estado,evidencia,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref,created_at,updated_at,primera_vez,ultima_vez)
 VALUES(gen_random_uuid(),'LF-PE10-C3-BROWSER-RAW-DURABILITY-20261015-001','PROFILE_EVOLUTION','La captura GPT por Chrome carecía de salida RAW durable autorizada','Coordinador Chrome completó 7 respuestas y dictamen, pero solo conservó hashes/enlaces y localStorage. Fue necesario recuperar ZIP y registrar 8 eventos por Migration Merge Train. Captura de chat no demuestra firma del proveedor.','El flujo de coordinación no resolvió antes de despachar el destino de escritura aprobado. La disponibilidad de lectura de Supabase se confundió con transporte de salida bidireccional; usar Chrome no otorga permisos DB ni atestación.','Se completan conversaciones GPT pero raw queda en DOM/localStorage, y eventos HANDOFF se confunden con RESULTADOS; la revisión no puede verificar pares o conservar evidencia duradera sin recuperación adicional.','Resolver recepción de RAW y ruta ACT-0001 antes de despachar. Tras cada ejecución usar contenido UTF-8 exacto, SHA-256 y evento append-only existente RAW_CAPTURE_BATCH_PREPARED por Operation autorizada o Train; si la ruta no existe, exportar ZIP persistente inmediatamente. No inventar recibos ni credenciales.','Evento recuperación 21036; eventos capturados 21041..21048 todos SHA-256 coincidente post-Train PR #2727; no existe evidencia provider-attested. Envío de instrucciones 21022..21026 no equivale a ejecución.','HIGH',1,'PROFILE_UPDATER_EVOLUTION_IMPLEMENTATION_V1/PE10_C3','#2717;#2723;#2727','ACTIVO','supabase://public.lf_eventos/21022;supabase://public.lf_eventos/21036;supabase://public.lf_eventos/21041;supabase://public.lf_eventos/21048','construction',ARRAY['Architect']::text[],'UNCLASSIFIED_WITH_REASON','DESTINATION_READBACK','GPT_BROWSER_CAPTURE_TRANSPORT','https://github.com/cristhianlujan/claude-persona-lf-patch/pull/2727',clock_timestamp(),clock_timestamp(),clock_timestamp(),clock_timestamp());
 END IF;
 SELECT count(*) INTO v_count FROM public.lf_error_knowledge WHERE codigo='LF-PE10-C3-BROWSER-RAW-DURABILITY-20261015-001' AND titulo='La captura GPT por Chrome carecía de salida RAW durable autorizada' AND causa_raiz='El flujo de coordinación no resolvió antes de despachar el destino de escritura aprobado. La disponibilidad de lectura de Supabase se confundió con transporte de salida bidireccional; usar Chrome no otorga permisos DB ni atestación.' AND prevencion='Resolver recepción de RAW y ruta ACT-0001 antes de despachar. Tras cada ejecución usar contenido UTF-8 exacto, SHA-256 y evento append-only existente RAW_CAPTURE_BATCH_PREPARED por Operation autorizada o Train; si la ruta no existe, exportar ZIP persistente inmediatamente. No inventar recibos ni credenciales.';
 IF v_count<>1 THEN RAISE EXCEPTION 'PE10_EKB_READBACK_MISMATCH_2'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-PE10-C3-UNBOUNDED-EVALUATION-LOOP-20261015-001') THEN
 INSERT INTO public.lf_error_knowledge(id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,lote_origen,pr,estado,evidencia,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref,created_at,updated_at,primera_vez,ultima_vez)
 VALUES(gen_random_uuid(),'LF-PE10-C3-UNBOUNDED-EVALUATION-LOOP-20261015-001','PROFILE_EVOLUTION','Pruebas repetidas sin regla de parada por mejora material','PE10_C3 acumuló comparaciones y correcciones semánticas/estructurales. Última pareja: UI candidato mejor en razonamiento local (8 vs 6 según dictamen no atestado); Product empate de decisión con mejora solo estructural. Mantener abierta la evidencia no justifica repetir todos los casos.','Se trató la ausencia de mejora experta certificada como motivo para generar nuevos lotes, mezclando iteración del método, comparación de desempeño y revisión independiente de procedencia. No se congelaba el resultado NO_QUALIFIED_GAIN.','Ronda adicional propuesta después de un empate/falta de recibo independiente; sin cambio causal del método, el mismo requisito reaparece como ''más pruebas''.','Un paquete pareado congelado, una reparación del fallo demostrado y como máximo su comprobación acotada. Empate/FAIL/no TO-BE => STOP y ajuste del método o NO_QUALIFIED_GAIN; no extender benchmark por validación o firma faltante. Mantener verificación transaccional posterior de cutover como checkpoint diferente.','Comparación RAW eventos 21041..21048, reviewer RAW 21048 (ganancia_material_experimental_demostrada=false, independencia no acreditada); condiciones independientes PE10_C3 siguen con 0 receipt canonico y 2 de 6 pasos, por lo que el bloqueo es fuente/certificación y no más casos.','MEDIUM',1,'PROFILE_UPDATER_EVOLUTION_IMPLEMENTATION_V1/PE10_C3','#2706;#2707','ACTIVO','supabase://public.lf_eventos/21041;supabase://public.lf_eventos/21048;supabase://programacion.engineering_plan_units/PROFILE_UPDATER_EVOLUTION_IMPLEMENTATION_V1/PE10','construction',ARRAY['Architect']::text[],'UNCLASSIFIED_WITH_REASON','FROZEN_EVAL_STOP_RULE','PROFILE_EVOLUTION_EVALUATION_STOP','https://github.com/cristhianlujan/claude-persona-lf-patch/pull/2707',clock_timestamp(),clock_timestamp(),clock_timestamp(),clock_timestamp());
 END IF;
 SELECT count(*) INTO v_count FROM public.lf_error_knowledge WHERE codigo='LF-PE10-C3-UNBOUNDED-EVALUATION-LOOP-20261015-001' AND titulo='Pruebas repetidas sin regla de parada por mejora material' AND causa_raiz='Se trató la ausencia de mejora experta certificada como motivo para generar nuevos lotes, mezclando iteración del método, comparación de desempeño y revisión independiente de procedencia. No se congelaba el resultado NO_QUALIFIED_GAIN.' AND prevencion='Un paquete pareado congelado, una reparación del fallo demostrado y como máximo su comprobación acotada. Empate/FAIL/no TO-BE => STOP y ajuste del método o NO_QUALIFIED_GAIN; no extender benchmark por validación o firma faltante. Mantener verificación transaccional posterior de cutover como checkpoint diferente.';
 IF v_count<>1 THEN RAISE EXCEPTION 'PE10_EKB_READBACK_MISMATCH_3'; END IF;
END
$pe10_ekb$;
COMMIT;
